"""Large-core validation: peeler vs simple peeler, and two-pass marginals vs
evidence-clamped forward elimination."""
import json, random, sys, time
sys.path.insert(0, '/workspace/tmp')
sys.path.insert(0, '/workspace/submission')
import ref, main as M


def forward_Z(factors, n):
    """Plain forward bucket elimination partition function."""
    if n == 0:
        return 1
    bucket = [[] for _ in range(n)]
    for f in factors:
        bucket[min(f[0])].append(f)
    children = [[] for _ in range(n)]
    msg = [None] * n
    Z = 1
    for i in range(n):
        pots = list(bucket[i])
        for c in children[i]:
            pots.append(msg[c])
        scope, table = M.factor_product(pots)
        mscope, mtable = M.sum_out_var(scope, table, i)
        msg[i] = (mscope, mtable)
        if mscope:
            children[mscope[0]].append(i)
        else:
            Z *= mtable.get((), 0)
            if Z == 0:
                return 0
    return Z


def Z_evidence(factors, n, var, val):
    clamped = []
    for (scope, table) in factors:
        if var in scope:
            k = scope.index(var)
            nt = {key: v for key, v in table.items() if key[k] == val}
            clamped.append((scope, nt))
        else:
            clamped.append((scope, table))
    return forward_Z(clamped, n)


def gen_big(seed):
    rnd = random.Random(seed)
    nn = rnd.randint(6, 26)
    nodes = list(range(1, nn + 1))
    rib = []
    for _ in range(rnd.randint(3, 30)):
        ln = rnd.randint(2, min(9, nn))
        p = rnd.sample(nodes, ln)
        raw = []
        for x in p:
            raw.append(x)
            if rnd.random() < 0.15:
                raw.append(x)
        rib.append({'path': raw, 'count': rnd.randint(1, 6)})
    ixps = [n for n in nodes if rnd.random() < 0.1][:2]
    agg = {}
    for rec in rib:
        p = ref.normalize(rec['path'], set(ixps))
        if len(p) < 2 or len(set(p)) != len(p):
            continue
        agg[tuple(p)] = agg.get(tuple(p), 0) + rec['count']
    if not agg:
        return None
    final, rounds = ref.ref_peel(agg)
    core = set()
    for p in final:
        for i in range(len(p) - 1):
            core.add(ref.canon(p[i], p[i + 1]))
    if not core or len(core) > 64:
        return None
    occs = ref.ref_occurrences(final)
    adj = ref.scope_graph(occs, core)
    order = ref.find_order(adj)
    if order is None:
        return None
    return {'agg': agg, 'final': final, 'rounds': rounds, 'core': core,
            'order': order, 'occs': occs, 'rib': rib, 'ixps': ixps}


def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    fails = 0
    tested = 0
    biggest = 0
    for seed in range(lo, hi):
        g = gen_big(seed)
        if g is None:
            continue
        # (a) peeling agreement
        f_mine, r_mine = M.peel(list(g['agg'].items()))
        if f_mine != g['final'] or r_mine != g['rounds']:
            print('seed', seed, 'PEELING MISMATCH')
            print(' agg', g['agg'])
            print(' mine', f_mine, r_mine)
            print(' ref ', g['final'], g['rounds'])
            fails += 1
            if fails > 2:
                break
            continue
        # (b) inference agreement
        order = g['order']
        vi = {l: i for i, l in enumerate(order)}
        factors = [M.build_factor(l, g['occs'][l], vi) for l in order]
        n = len(order)
        biggest = max(biggest, n)
        Z, marg = M.infer(factors, n)
        Zc = forward_Z(factors, n)
        if Z != Zc:
            print('seed', seed, 'Z MISMATCH', Z, Zc)
            fails += 1
            continue
        if Z == 0:
            continue
        bad = None
        for i in range(n):
            for t in (0, 1, 2):
                ze = Z_evidence(factors, n, i, t)
                if ze != marg[i][t]:
                    bad = (i, t, ze, marg[i][t])
                    break
            if bad:
                break
        if bad:
            print('seed', seed, 'MARGINAL MISMATCH', bad, 'ncore', n)
            fails += 1
            if fails > 2:
                break
        tested += 1
    print('tested', tested, 'fails', fails, 'max core links', biggest)
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
